    {"dt": "Expense Claim Detail", "fieldname": "custom_adjusted_amount", "label": "Adjusted Amount", "fieldtype": "Currency", "insert_after": "custom_adjusted", "read_only": 1},
    {"dt": "Expense Claim Detail", "fieldname": "custom_adjust_reason", "label": "Adjust Reason", "fieldtype": "Small Text", "insert_after": "custom_adjusted_amount", "read_only": 1},
    {"dt": "Expense Claim Detail", "fieldname": "custom_adjusted_by", "label": "Adjusted By", "fieldtype": "Link", "options": "User", "insert_after": "custom_adjust_reason", "read_only": 1},
    {"dt": "Expense Claim Detail", "fieldname": "custom_adjusted_on", "label": "Adjusted On", "fieldtype": "Datetime", "insert_after": "custom_adjusted_by", "read_only": 1},
